import math, sys
sys.path.insert(0, "/mnt/c/Data/Operations/spaces/space04/solverA/task009")
from app import Linear, TanhSequence

EPS=1e-6
def central(f): return (f(EPS)-f(-EPS))/(2*EPS)
W=[0.4,-0.3]; B=0.15
XS=[0.8,-0.5,1.2,-0.7,0.3]; GO=[0.3,-0.6,0.9,-0.2,0.5]

def ref(w,b,xs,h0,trunc,carry,frozen=None):
    outs=[]; h=h0
    for i,x in enumerate(xs):
        if trunc is not None and i%trunc==0:
            if i==0: h=h0
            elif frozen is not None: h=frozen[i]
            elif carry: h=outs[-1]
            else: h=0.0
        h=math.tanh(w[0]*x+w[1]*h+b); outs.append(h)
    return outs

def loss(w,b,xs,h0,go,seed,trunc,carry,frozen):
    o=ref(w,b,xs,h0,trunc,carry,frozen)
    return sum(g*z for g,z in zip(go,o))+(seed*o[-1] if o else seed*h0)

worst=0.0
for trunc,carry,h0,seed in [(None,False,0,0),(None,False,0.25,0.35),(2,False,0,0),
                            (2,True,0.25,0.35),(1,False,0,0),(1,True,0.25,0.35),
                            (3,True,0,0.35),(100,False,0,0)]:
    base=ref(W,B,XS,h0,trunc,carry)
    frozen={}
    if trunc is not None:
        for i in range(1,len(XS)):
            if i%trunc==0: frozen[i]=base[i-1] if carry else 0.0
    s=TanhSequence(Linear(list(W),B)); s.forward([[x] for x in XS],trunc,carry,h0)
    if seed: ig,gi=s.backward_with_initial_hidden(GO,seed)
    else: ig=s.backward(GO); _,gi=TanhSequence(Linear(list(W),B)) and (None,0)
    g=s.linear.grad
    errs=[]
    for t in range(5):
        fd=central(lambda d,t=t: loss(W,B,[a+(d if k==t else 0) for k,a in enumerate(XS)],h0,GO,seed,trunc,carry,frozen))
        errs.append(abs(ig[t]-fd))
    errs.append(abs(g[0]-central(lambda d: loss([W[0]+d,W[1]],B,XS,h0,GO,seed,trunc,carry,frozen))))
    errs.append(abs(g[1]-central(lambda d: loss([W[0],W[1]+d],B,XS,h0,GO,seed,trunc,carry,frozen))))
    errs.append(abs(g[2] if False else s.linear.grad_bias-central(lambda d: loss(W,B+d,XS,h0,GO,seed,trunc,carry,frozen))))
    if XS: errs.append(abs(gi-central(lambda d: loss(W,B,XS,h0+d,GO,seed,trunc,carry,frozen))))
    m=max(errs); worst=max(worst,m)
    print(f"trunc={trunc} carry={carry} h0={h0} seed={seed}: max abs err {m:.3e}")
print("WORST", f"{worst:.3e}", " tolerance 1e-7 -> margin factor", 1e-7/worst)
